`timescale 1ns/1ps
// CB16c-COLL 10-22 (ALT to the flat qfd_coll_face_*_pl leaves; STEWARD-QKc / SQC-CB16c): regional split of a Qwen
// collective face. GENERATED by mk_rtl.py from the face RTL at 2919e5896 by exact substitutions (do not hand-edit):
//   qfd_static_ch546_regional_ox  = qfd_static_ch546_regional with o_data = rd_stage (its o_data rank -> rx slice)
//   ot_qwen_static_slot_link_plx  = ot_qwen_static_slot_link_pl with the expected RX tokens LK + XR edges late
//   qfd_coll_static_face_x        = qfd_coll_static_face (SAFE/PLAND/TOK_REG/REGIONAL form) with td_q -> tx slice,
//                                   o_data -> rx slice, phy_tx +XT (slice), phy_rx +XR (slice) consumed by the calendar

module qfd_static_ch546_regional_ox (
 input wire wck,rck,rst_n,
 input wire w_slot,input wire [5:0] w_addr,input wire w_version,
 input wire i_valid,input wire [545:0] i_data,
 input wire r_slot,input wire [5:0] r_addr,input wire r_version,
 output reg o_valid,output wire [545:0] o_data,
 output reg w_fault,r_fault);
 wire [4:0] wrs;
 wire [8:0] rrs;
 ot_qwen_slot_reset_copies #(.COPIES(5))u_wr(.clk(wck),.rst_n(rst_n),.released(wrs));
 ot_qwen_slot_reset_copies #(.COPIES(9))u_rr(.clk(rck),.rst_n(rst_n),.released(rrs));
 (* keep="true",dont_touch="true" *)reg [3:0] wp_q,wv_q;
 reg rp,rv;
 reg [5:0] wa,ra;
 reg [545:0] wd,rd_stage;
 reg [63:0] published,seen;
 (* async_reg="true" *)reg [63:0] pub_meta,pub_sync,seen_meta,seen_sync;
 reg [2:0] read_pipe;
 wire [545:0] memory_data;
 always @(posedge wck or negedge wrs[0])begin
  if(!wrs[0])begin wp_q<=0;wv_q<=0;w_fault<=0;end
  else begin wp_q<={4{w_slot}};wv_q<={4{w_version}};
    w_fault<=w_fault|(w_slot&&(i_valid!==1'b1));end
 end
 for(genvar g=0;g<4;g=g+1)begin:g_write
  for(genvar b=0;b<16;b=b+1)begin:g_bit
   always @(posedge wck or negedge wrs[g+1])
    if(!wrs[g+1])begin published[g*16+b]<=0;seen[g*16+b]<=0;end
    else if(wp_q[g] && wa==g*16+b)begin published[g*16+b]<=wv_q[g];seen[g*16+b]<=1;end
  end
 end
 always @(posedge wck)begin wa<=w_addr;wd<=i_data;end
 for(genvar g=0;g<8;g=g+1)begin:g_publication
  always @(posedge rck or negedge rrs[g+1])
   if(!rrs[g+1])begin pub_meta[g*8+:8]<=0;pub_sync[g*8+:8]<=0;seen_meta[g*8+:8]<=0;seen_sync[g*8+:8]<=0;end
   else begin pub_meta[g*8+:8]<=published[g*8+:8];pub_sync[g*8+:8]<=pub_meta[g*8+:8];
    seen_meta[g*8+:8]<=seen[g*8+:8];seen_sync[g*8+:8]<=seen_meta[g*8+:8];end
 end
 wire [3:0] selected_p,selected_s;
 for(genvar g=0;g<4;g=g+1)begin:g_read_select
  // Independent publication/seen selectors leave room for the SRAM
  // address alias: source4's shared selector actually mapped33 loads.
  (* keep="true",dont_touch="true" *)reg [3:0] ra_p,ra_s;
  wire [15:0] p_lane=pub_sync[g*16+:16];
  wire [15:0] s_lane=seen_sync[g*16+:16];
  always @(posedge rck)begin ra_p<=r_addr[3:0];ra_s<=r_addr[3:0];end
  assign selected_p[g]=p_lane[ra_p];
  assign selected_s[g]=s_lane[ra_s];
 end
 wire read_p=selected_p[ra[5:4]];
 wire read_s=selected_s[ra[5:4]];
 always @(posedge rck or negedge rrs[0])begin
  if(!rrs[0])begin rp<=0;rv<=0;read_pipe<=0;o_valid<=0;r_fault<=0;end
  else begin rp<=r_slot;rv<=r_version;read_pipe<={read_pipe[1:0],r_slot};
`ifdef OT_STATIC_MUT_LATENCY
   o_valid<=read_pipe[1];
`else
   o_valid<=read_pipe[2];
`endif
   r_fault<=r_fault|(rp&&(read_s!==1'b1||read_p!==rv));
  end
 end
 always @(posedge rck)begin ra<=r_addr;rd_stage<=memory_data;end
 // CB16c-COLL: the o_data stage is the face rx_data slice (qfd_coll_eslice182 on an rx_rck entry), outside.
 assign o_data=rd_stage;
 ot_sram_1r1w2c_64x546_m1 u_mem(
 .wclk(wck),.rclk(rck),.r_ce_in(rp),.r_addr_in(ra),.rd_out(memory_data),
 .w_ce_in(wp_q[0]),.w_addr_in(wa),.wd_in(wd),.w_mask_in({546{1'b1}}));
endmodule

module ot_qwen_static_slot_link_plx #(
    parameter integer FW=548, CW=16, PW=FW+19+CW, MUT=0, SAFE=0, LD=2, LK=1, BWREG=1, BLOCAL=0, XR=1
)(
    input wire [4:0] ck,
    input wire phy_ck,
    input wire rst_n, epoch_begin,
    input wire [7:0] epoch,
    input wire wr_v, wr_observed_v,
    input wire [5:0] wr_slot,
    input wire [FW-1:0] wr_flit,
    input wire rd_v,
    input wire [5:0] rd_slot,
    input wire rx_expect_v,
    input wire [5:0] rx_expect_slot,
    input wire p_tx_up,
    output wire p_tx_v,
    output wire [PW-1:0] p_tx_flit,
    input wire p_rx_v,
    input wire [PW-1:0] p_rx_flit,
    output wire rx_v,
    output wire [FW-1:0] rx_flit,
    output wire epoch_abort,
    output wire [7:0] fault_cause
);
    localparam integer BW=137;
    wire [4*BW-1:0] wd={{(4*BW-FW){1'b0}},wr_flit};
    wire [4*BW-1:0] rd;
    wire c_abort;
    wire issue_write=wr_v && !c_abort && !epoch_begin;
    // QW2-COLL 10-21 BWREG: the bank write port + read address are captured by codec-core registers (ck[0], codec band,
    // abutting both bank columns) before the SRAM; the bank clock pins stay pure hard entries (one port -> one macro
    // clock pin; a glue root over the bank entries is refused by clock_entry_constraints).  The
    // r_plg gate failed cross_clock SETUP (210 ps inter-entry uncertainty) on direct crossings with logic into the bank
    // macro pins: epoch_begin (cal_lck) / c_abort (codec0) -> we, u_tx o_data (tx_rck macro) -> din.  Now every
    // crossing ends at a flop in the bank's own entry and the flop -> SRAM path is single-entry.  Write lands 1 edge
    // later (static calendar: the replay read of a slot is far behind its write).
`ifdef OT_COLL_BANK_LOCAL
    localparam integer USE_LOCAL_BANK=1;
`else
    localparam integer USE_LOCAL_BANK=BLOCAL;
`endif
    for(genvar b=0;b<4;b=b+1)begin:g_bank
      if(USE_LOCAL_BANK) begin:g_local
        // The landing and SRAM share a real local clock tree INSIDE this
        // hardened child. The face clock entry remains port -> child clock.
        ot_coll_bank_land137 u_store(.ck(ck[b+1]),.we(issue_write),
          .wa(wr_slot),.ra(rd_slot),.rd_v(rd_v),.din(wd[b*BW+:BW]),
          .dout(rd[b*BW+:BW]));
      end else begin:g_legacy
        wire bwe;
        wire [5:0] bwa, bra;
        wire [BW-1:0] bdin;
        if (BWREG) begin : g_wreg
            reg we_q;
            reg [5:0] wa_q;
            reg [BW-1:0] din_q;
            // read address: bank-entry copy of the calendar read counter, one edge AHEAD (rd_slot + rd_v is the counter's
            // next value, rd_v = its enable), so ra_q == rd_slot in every cycle and the read timing is unchanged.  p_plg
            // failed cross_clock SETUP -259.6 ps on u_txcal.u_cr.c[4] (cal_lck, W cal channel) -> bank ra.
            reg [5:0] ra_q;
            always @(posedge ck[0]) begin we_q <= issue_write; wa_q <= wr_slot; din_q <= wd[b*BW+:BW]; ra_q <= rd_slot + {5'd0, rd_v}; end
            assign bwe = we_q; assign bwa = wa_q; assign bdin = din_q; assign bra = ra_q;
        end else begin : g_wdir
            assign bwe = issue_write; assign bwa = wr_slot; assign bdin = wd[b*BW+:BW]; assign bra = rd_slot;
        end
`ifdef OT_QFD_FACE_HARD
        ot_qkvd_llr_replay_sram_leaf u_store(
`else
        ot_qkvd_llr_replay_sram_leaf #(.W(BW),.MUT(MUT==3 && b==0)) u_store(
`endif
            .ck(ck[b+1]),.we(bwe),.wa(bwa),.ra(bra),
            .din(bdin),.dout(rd[b*BW+:BW]));
      end
    end
    // region resets: one 2-edge synchroniser per clock, kept copies per ring side
    wire [2:0] rs_c;
    wire [1:0] rs_p;
    ot_qwen_slot_reset_copies #(.COPIES(3)) u_rs_c(.clk(ck[0]),.rst_n(rst_n),.released(rs_c));
    ot_qwen_slot_reset_copies #(.COPIES(2)) u_rs_p(.clk(phy_ck),.rst_n(rst_n),.released(rs_p));
    // RX: pins -> ring (phy_ck) -> controller pin registers (ck[0]); +LK edges
    wire [PW-1:0] rx_flit_l;
    wire rx_v_l, up_l;
    ot_coll_meso_ring #(.W(PW+2),.D(LD),.K(LK),.C(2),.REG_OUT(0)) u_rx_land(
        .ck_w(phy_ck),.rs_w(rs_p[0]),.ck_r(ck[0]),.rs_r(rs_c[0]),
        .d({p_rx_flit,p_tx_up,p_rx_v}),.q({rx_flit_l,up_l,rx_v_l}));
    // the expected-frame tokens follow the landed frame by the same LK edges (control bit reset)
    // CB16c-COLL: the frame reaches this ring XR edges after the face pin (phy_rx slice + phy_rx_valid/phy_up regs),
    // so the expected tokens (issued at the pin cycle) follow by LK + XR edges.
`ifdef OT_CB16C_MUT_NOXR
    localparam integer LE = LK;
`else
    localparam integer LE = LK + XR;
`endif
    reg [LE-1:0] ev_q;
    reg [6*LE-1:0] es_q;
    always @(posedge ck[0]) if(!rs_c[2]) ev_q<={LE{1'b0}}; else ev_q<={ev_q,rx_expect_v};
    always @(posedge ck[0]) es_q<={es_q,rx_expect_slot};
    wire ev_l=ev_q[LE-1];
    wire [5:0] es_l=es_q[6*LE-1-:6];
    // TX: controller registers (ck[0]) -> ring -> PHY output pin registers (phy_ck); +1+LK edges
    wire c_tx_v;
    wire [PW-1:0] c_tx_flit;
    wire [7:0] c_cause;
    ot_qwen_static_slot_ctl #(.FW(FW),.CW(CW),.PW(PW),.SAFE(SAFE)) u_ctl (
        .clk(ck[0]),.q_data(rd[FW-1:0]),
        .rst_n(rst_n), .epoch_begin(epoch_begin), .epoch(epoch), .wr_v(wr_v), .wr_observed_v(wr_observed_v), .wr_slot(wr_slot),
        .rd_v(rd_v), .rd_slot(rd_slot), .rx_expect_v(ev_l), .rx_expect_slot(es_l), .p_tx_up(up_l), .p_tx_v(c_tx_v),
        .p_tx_flit(c_tx_flit), .p_rx_v(rx_v_l), .p_rx_flit(rx_flit_l), .rx_v(rx_v), .rx_flit(rx_flit),
        .epoch_abort(c_abort), .fault_cause(c_cause));
    ot_coll_meso_ring #(.W(PW+10),.D(LD),.K(LK),.C(10),.REG_OUT(1)) u_tx_land(
        .ck_w(ck[0]),.rs_w(rs_c[1]),.ck_r(phy_ck),.rs_r(rs_p[1]),
        .d({c_tx_flit,c_cause,c_abort,c_tx_v}),.q({p_tx_flit,fault_cause,epoch_abort,p_tx_v}));
endmodule

module qfd_coll_static_face_x #(
 parameter integer FW=546, PHY=339, L=376, R=0, PEER_R=R, KC=4, KW=2,
 parameter integer PW=FW+51, TOK_REG=0, SAFE=0,
 // PLAND (QW-COLLIO2 10-21, default 0 = byte-identical): codec PHY pins in their own clock region (codec_phy_ck, a
 // second entry of the codec0 die clock) landed to the codec core region by mesochronous rings (ot_coll_phy_land.sv,
 // depth PLD, offset PLK). TX +1+PLK edges, RX +PLK edges: the calendar below consumes them exactly; the caller's L
 // must be the original L + 1 + 2*PLK (S1: 378 -> 381 at PLD2/PLK1). Needs SAFE=1.
 PLAND=0, PLD=2, PLK=1,
 // CB16c-COLL 10-22: XT extra TX edges after phy_tx (face slice), XR extra RX edges before the RX ring (face slice +
 // phy_rx_valid / phy_up regs). Caller L = original L + XT + XR.
 XT=1, XR=1
)(
 input wire cal_ck,cal_lck,tx_wck,tx_rck,rx_wck,rx_rck,
 input wire [4:0] codec_ck,input wire codec_phy_ck,input wire rst_n,
 input wire tx_slot,peer_slot,input wire tx_valid,input wire[FW-1:0]tx_data,
 output wire rx_valid,output wire[FW-1:0]rx_data,
 input wire phy_up,phy_rx_valid,input wire[PW-1:0]phy_rx,
 output wire phy_tx_valid,output wire[PW-1:0]phy_tx,
 output wire phy_tx_slot,phy_rx_slot,
 output wire[3:0]cdc_fault,output wire epoch_abort,output wire[7:0]fault_cause
);
 wire tx_slot_i,peer_slot_i,tx_valid_i;wire[FW-1:0]tx_data_i;wire[3:0]cdc_fault_i;
 if(TOK_REG)begin:g_tok_reg
  reg ts_q,tv_q,ps_q;reg[3:0]cf_q;
  // CB16c-COLL: td_q is the face tx_data slice (outside, on its own cal_ck entry); tx_data arrives registered.
  always @(posedge cal_ck)begin ts_q<=tx_slot;tv_q<=tx_valid;ps_q<=peer_slot;end
`ifdef OT_COLL_REGIONAL
  // Sticky diagnostic returns cross in fixed-slot rings, rather than a
  // direct hard-child status wire into the calendar pin register.
  wire [3:0] cf_landed;
  wire [3:0] cf_roots={rx_rck,rx_wck,tx_rck,tx_wck};
  for(genvar f=0;f<4;f=f+1)begin:g_fault_land
    wire rs_f;wire [1:0] fq;
    ot_reset_sync u_fr(.clk(cf_roots[f]),.async_rst_n(rst_n),.sync_rst_n(rs_f));
    ot_coll_meso_ring #(.W(2),.C(1),.D(4),.K(2),.REG_OUT(1))u_ring(
      .ck_w(cf_roots[f]),.rs_w(rs_f),.ck_r(cal_ck),.rs_r(rs_core[0]),
      .d({1'b0,cdc_fault_i[f]}),.q(fq));
    assign cf_landed[f]=fq[0];
  end
  always @(posedge cal_ck)cf_q<=cf_landed;
`else
  always @(posedge cal_ck)cf_q<=cdc_fault_i;
`endif
  assign {tx_slot_i,tx_valid_i,tx_data_i,peer_slot_i}={ts_q,tv_q,tx_data,ps_q};assign cdc_fault=cf_q;
 end else begin:g_tok_direct
  assign {tx_slot_i,tx_valid_i,tx_data_i,peer_slot_i}={tx_slot,tx_valid,tx_data,peer_slot};assign cdc_fault=cdc_fault_i;
 end
 initial if(TOK_REG && KC<2)$error("qfd_coll_static_face TOK_REG needs KC>=2");
 wire rs_c,rs_l;
 wire[2:0]rs_core;wire[5:0]rs_link;
 if(SAFE)begin:g_safe_reset
  // Kept local copies release at the original two-edge depth, not one
  // common 400-load reset output followed by extra startup cycles.
  // QW-COLLIO 10-20: rs_core[2] now feeds the RX core counters, +2 link copies so no copy drives >32 reset pins (native census 33/40).
  ot_qwen_slot_reset_copies #(.COPIES(3))u_core(.clk(cal_ck),.rst_n(rst_n),.released(rs_core));
  ot_qwen_slot_reset_copies #(.COPIES(6))u_link(.clk(cal_lck),.rst_n(rst_n),.released(rs_link));
 end else begin:g_original_reset
  ot_reset_sync u_rc(.clk(cal_ck),.async_rst_n(rst_n),.sync_rst_n(rs_c));
  ot_reset_sync u_rl(.clk(cal_lck),.async_rst_n(rst_n),.sync_rst_n(rs_l));
  assign rs_core={3{rs_c}};assign rs_link={6{rs_l}};
 end
 reg[1:0] ec;reg epoch_begin;
 always @(posedge cal_lck or negedge rs_link[2])
 if(!rs_link[2])begin ec<=0;epoch_begin<=0;end else begin
 if(ec!=3)ec<=ec+1'b1;epoch_begin<=(ec==1);end
 localparam integer PTX = (PLAND ? 1+PLK : 0) + XT;   // extra TX edges controller -> PHY pin (incl. the face slice)
`ifdef OT_CB16C_MUT_NOXR
 localparam integer PRX = PLAND ? PLK : 0;
`else
 localparam integer PRX = (PLAND ? PLK : 0) + XR;     // extra RX edges PHY pin -> controller (incl. the face slice)
`endif
`ifdef OT_CB16C_MUT_NOXT
 localparam integer PSL = 4 + PTX - XT;
`else
 localparam integer PSL = 4 + PTX;
`endif
 initial if(PLAND && !SAFE)$error("qfd_coll_static_face PLAND needs SAFE=1");
 wire tws,twsver,trs,trsver,wr_v,rd_v,rxe,rws,rwv,rrs,rrv;
 wire[5:0]twa,tra,wr_slot,rd_slot,rx_slot,rwa,rra;
 ot_coll_lcal_tx #(.KC(KC-TOK_REG),.KW(KW),.SAFE_RING(SAFE),.LAND_CORE(SAFE)) u_txcal(
 .clk(cal_ck),.lck(cal_lck),.rs_c(rs_core[0]),.rs_l(rs_link[0]),.rs_l2(rs_link[4]),.slot(tx_slot_i),
 .w_slot(tws),.w_addr(twa),.w_version(twsver),.r_slot(trs),.r_addr(tra),.r_version(trsver),
 .wr_v(wr_v),.wr_slot(wr_slot),.rd_v(rd_v),.rd_slot(rd_slot));
 ot_coll_lcal_rx #(.KC(KC-TOK_REG),.KW(KW),.PHY(PHY+PTX),.L(L-TOK_REG),.R(R),.PEER_R(PEER_R),.SAFE_RING(SAFE),.LAND_CORE(SAFE),.WX(PRX))u_rxcal(
 .clk(cal_ck),.lck(cal_lck),.rs_c(rs_core[1]),.rs_l(rs_link[1]),.rs_c2(rs_core[2]),.rs_l2(rs_link[5]),.exp(peer_slot_i),
 .rx_expect_v(rxe),.rx_expect_slot(rx_slot),.w_slot(rws),.w_addr(rwa),.w_version(rwv),
 .r_slot(rrs),.r_addr(rra),.r_version(rrv));
 // Expected PHY ownership comes only from compiled calendar reads, never
 // from observed producer/codec validity. Matches actual codec TX3 boundary.
 if(SAFE)begin:g_safe_phy_slots
  ot_coll_dly1 #(.N(PSL),.SAFE_RING(1))u_slots(.clk(cal_lck),.rs_n(rs_link[3]),.d(rd_v),.q(phy_tx_slot));
 end else begin:g_original_phy_slots
  reg[3:0]phy_slots;
  always @(posedge cal_lck or negedge rs_link[3])
  if(!rs_link[3])phy_slots<=0;else if(epoch_begin)phy_slots<=0;else phy_slots<={phy_slots[2:0],rd_v};
  assign phy_tx_slot=phy_slots[3];
 end
 assign phy_rx_slot=rxe;
 wire tx_observed,codec_valid;wire[FW-1:0]tx_word,codec_data;
 wire[545:0]tx_full,rx_full;
 assign tx_word=tx_full[FW-1:0];assign rx_data=rx_full[FW-1:0];
 // Source-identical storage to qfd_io_xfifo_static: R514 pads its high32
 // storage bits, retaining the same546-bit physical CDC master and latency.
 qfd_static_ch546_regional u_tx(
.wck(tx_wck),.rck(tx_rck),.rst_n(rst_n),
 .w_slot(tws),.w_addr(twa),.w_version(twsver),.i_valid(tx_valid_i),.i_data({{(546-FW){1'b0}},tx_data_i}),
 .r_slot(trs),.r_addr(tra),.r_version(trsver),.o_valid(tx_observed),.o_data(tx_full),.w_fault(cdc_fault_i[0]),.r_fault(cdc_fault_i[1]));
 qfd_static_ch546_regional_ox u_rx(
.wck(rx_wck),.rck(rx_rck),.rst_n(rst_n),
 .w_slot(rws),.w_addr(rwa),.w_version(rwv),.i_valid(codec_valid),.i_data({{(546-FW){1'b0}},codec_data}),
 .r_slot(rrs),.r_addr(rra),.r_version(rrv),.o_valid(rx_valid),.o_data(rx_full),.w_fault(cdc_fault_i[2]),.r_fault(cdc_fault_i[3]));
 initial if(FW!=546 && FW!=514)$error("collectiveface546/514only");
 if(PLAND)begin:g_codec_pl
 wire c_ptv,x_prv,x_up;
 // CB16c-COLL XT/XR = 1: phy_tx (597) and phy_rx (597) ranks are the face E slices on codec0p entries; the 1-bit
 // valid / up companions get the same one edge here, on codec_phy_ck beside the body's PHY band.
 reg ptv_q,prv_q,up_q;
 always @(posedge codec_phy_ck)begin ptv_q<=c_ptv;prv_q<=phy_rx_valid;up_q<=phy_up;end
 assign phy_tx_valid=ptv_q;assign x_prv=prv_q;assign x_up=up_q;
 initial if(XT!=1 || XR!=1 || !PLAND || !SAFE || !TOK_REG)$error("qfd_coll_static_face_x: built for XT=XR=1, PLAND, SAFE, TOK_REG");
 ot_qwen_static_slot_link_plx #(.FW(FW),.CW(32),.SAFE(SAFE),.LD(PLD),.LK(PLK),.XR(XR))u_codec(.ck(codec_ck),.phy_ck(codec_phy_ck),.rst_n(rst_n),
 .epoch_begin(epoch_begin),.epoch(8'h01),.wr_v(wr_v),.wr_observed_v(tx_observed),.wr_slot(wr_slot),.wr_flit(tx_word),
 .rd_v(rd_v),.rd_slot(rd_slot),.rx_expect_v(rxe),.rx_expect_slot(rx_slot),
 .p_tx_up(x_up),.p_tx_v(c_ptv),.p_tx_flit(phy_tx),.p_rx_v(x_prv),.p_rx_flit(phy_rx),
 .rx_v(codec_valid),.rx_flit(codec_data),.epoch_abort(epoch_abort),.fault_cause(fault_cause));
 end else begin:g_codec
 ot_qwen_static_slot_link #(.FW(FW),.CW(32),.SAFE(SAFE))u_codec(.ck(codec_ck),.rst_n(rst_n),
